// One message, one worker that crashes once on first delivery.
// Broker redelivers anything it never saw acked. Count effects + losses.
function run(ackBeforeProcess) {
  let effects = 0, acked = false;
  for (let attempt = 1; attempt <= 3 && !acked; attempt++) {
    if (ackBeforeProcess) {
      acked = true;               // broker drops the message NOW
      if (attempt === 1) continue; // crash before any effect
    }
    effects++;                    // do the work (send the email)
    if (!ackBeforeProcess && attempt === 1) continue; // crash after effect, pre-ack
    acked = true;
  }
  return { effects: effects, lost: ackBeforeProcess && effects === 0 };
}
const early = run(true);
const late = run(false);
console.log('ack-before: effects=' + early.effects + ' lost=' + early.lost);
console.log('ack-after: effects=' + late.effects + ' lost=' + late.lost);
